package pzvrphysicality;
import java.lang.reflect.*;import java.util.*;import zombie.core.skinnedmodel.model.*;
/** Passive copy of the exact original FBX upload payload. No file parsing, VBO reads or asset requests. */
public final class NativeHeldFbxCpu {
 public record Data(float[] vertices,int[] faces,int revision){public Data{vertices=vertices.clone();faces=faces.clone();if(vertices.length<12||vertices.length>24000||vertices.length%3!=0||faces.length<3||faces.length>48000||faces.length%3!=0)throw new IllegalArgumentException("Phone FBX triangle extent");for(float value:vertices)if(!Float.isFinite(value))throw new IllegalArgumentException("Phone FBX vertex");for(int index:faces)if(index<0||index>=vertices.length/3)throw new IllegalArgumentException("Phone FBX index");}public float[] vertices(){return vertices.clone();}public int[] faces(){return faces.clone();}}
 private static final class Entry{final Data data;final String path;final float[] bounds;VertexBufferObject.VertexArray vertices;int[] faces;Object vbo;boolean loaded;Entry(Data d,String p,float[] b,VertexBufferObject.VertexArray v,int[] f){data=d;path=p;bounds=b;vertices=v;faces=f;}void released(){if(loaded&&vbo!=null){vertices=null;faces=null;}}}
 private record Scope(ModelMesh mesh,Object scene,Object imported,VertexBufferObject.VertexArray vertices,int[] faces,int revision,Data data,String path,float[] bounds,Thread owner,Entry entry){}
 private static final ThreadLocal<ArrayDeque<Scope>> scopes=new ThreadLocal<>();private static final Scope INACTIVE=new Scope(null,null,null,null,null,0,null,null,null,null,null);private static final WeakHashMap<ModelMesh,Entry> cache=new WeakHashMap<>(),pending=new WeakHashMap<>();
 private static volatile String detail="No original phone FBX CPU receipt";
 private static final ClassValue<Boolean> pinned=new ClassValue<>(){protected Boolean computeValue(Class<?> type){try{SdkPins.verify(type,SdkPins.GAME);return type.getName().equals("zombie.core.skinnedmodel.model.ModelMesh")||type.getName().equals("zombie.core.skinnedmodel.model.VertexBufferObject");}catch(Exception|LinkageError denied){return false;}}};
 private static Object field(Object source,String name)throws ReflectiveOperationException{var f=source.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(source);}
 private static String path(ModelMesh mesh){return mesh==null||mesh.getPath()==null?null:mesh.getPath().getPath();}
 private static boolean phone(String path){if(path==null)return false;var value=path.replace('\\','/').toLowerCase(Locale.ROOT);return value.endsWith("worlditems/cordlessphone")||value.endsWith("worlditems/cordlessphone.fbx");}
 private static float[] positions(VertexBufferObject.VertexArray vertices){if(vertices==null||vertices.numVertices<4||vertices.numVertices>8000)throw new IllegalArgumentException("Phone FBX vertex budget");var copy=new float[vertices.numVertices*3];for(int n=0;n<vertices.numVertices;n++)for(int c=0;c<3;c++)copy[n*3+c]=vertices.getElementFloat(n,0,c);return copy;}
 private static float[] bounds(float[] values){var result=new float[]{Float.POSITIVE_INFINITY,Float.POSITIVE_INFINITY,Float.POSITIVE_INFINITY,Float.NEGATIVE_INFINITY,Float.NEGATIVE_INFINITY,Float.NEGATIVE_INFINITY};for(int n=0;n<values.length;n++)if(Float.isFinite(values[n])){int axis=n%3;result[axis]=Math.min(result[axis],values[n]);result[axis+3]=Math.max(result[axis+3],values[n]);}else throw new IllegalArgumentException("Phone bounds finite");return result;}
 private static boolean bounds(ModelMesh mesh,float[] expected){if(mesh.minXyz==null||mesh.maxXyz==null||!mesh.minXyz.isFinite()||!mesh.maxXyz.isFinite())return false;float[] actual={mesh.minXyz.x,mesh.minXyz.y,mesh.minXyz.z,mesh.maxXyz.x,mesh.maxXyz.y,mesh.maxXyz.z};for(int n=0;n<6;n++)if(Math.abs(actual[n]-expected[n])>Math.max(.0001f,Math.abs(expected[n])*.0001f))return false;return true;}
 public static void begin(ModelMesh mesh,Object scene){begin(mesh,scene,false);}
 static void beginForTest(ModelMesh mesh,Object scene){begin(mesh,scene,true);}
 private static void begin(ModelMesh mesh,Object scene,boolean authored){var stack=scopes.get();if(stack==null){stack=new ArrayDeque<>();scopes.set(stack);}Scope scope=INACTIVE;
  try{if(mesh!=null&&(authored||pinned.get(mesh.getClass()))&&phone(path(mesh))&&scene!=null&&scene.getClass().getName().equals("zombie.core.skinnedmodel.model.jassimp.ProcessedAiScene")){synchronized(NativeHeldFbxCpu.class){cache.remove(mesh);pending.remove(mesh);}var imported=(List<?>)field(scene,"staticMeshes");if(imported.size()!=1)throw new IllegalArgumentException("Phone static FBX mesh selection");Object source=imported.get(0);var vertices=(VertexBufferObject.VertexArray)field(source,"verticesUnskinned");var faces=(int[])field(source,"elements");var data=new Data(positions(vertices),faces,Math.addExact(mesh.modificationCount,1));var bound=bounds(data.vertices);var entry=new Entry(data,path(mesh),bound,vertices,faces);scope=new Scope(mesh,scene,source,vertices,faces,mesh.modificationCount,data,path(mesh),bound,Thread.currentThread(),entry);synchronized(NativeHeldFbxCpu.class){if(pending.size()>=16&&!pending.containsKey(mesh)){pending.clear();cache.clear();}pending.put(mesh,entry);}}}
  catch(ReflectiveOperationException|RuntimeException|LinkageError unsupported){detail="Phone FBX CPU payload unavailable: "+unsupported.getClass().getSimpleName();}stack.push(scope);
 }
 public static void end(ModelMesh mesh,Throwable failure){var stack=scopes.get();if(stack==null||stack.isEmpty())return;var scope=stack.pop();try{
  if(scope==INACTIVE||failure!=null||mesh!=scope.mesh||Thread.currentThread()!=scope.owner||mesh.modificationCount!=scope.data.revision||!Objects.equals(scope.path,path(mesh))||!bounds(mesh,scope.bounds)||!Arrays.equals(scope.data.vertices,positions(scope.vertices))||!Arrays.equals(scope.data.faces,scope.faces))return;var imported=(List<?>)field(scope.scene,"staticMeshes");if(imported.size()!=1||imported.get(0)!=scope.imported||field(scope.imported,"verticesUnskinned")!=scope.vertices||field(scope.imported,"elements")!=scope.faces)return;
  synchronized(NativeHeldFbxCpu.class){if(pending.get(mesh)!=scope.entry)return;if(cache.size()>=16&&!cache.containsKey(mesh))cache.clear();scope.entry.loaded=true;scope.entry.released();cache.put(mesh,scope.entry);detail="Original phone FBX payload captured; matching native upload required";}
 }catch(ReflectiveOperationException|RuntimeException|LinkageError unavailable){detail="Phone FBX CPU receipt changed";}finally{if(scope!=INACTIVE&&!scope.entry.loaded)synchronized(NativeHeldFbxCpu.class){if(pending.get(scope.mesh)==scope.entry)pending.remove(scope.mesh);}if(stack.isEmpty())scopes.remove();}}
 /** Observe the original queued upload with the same CPU array identities, without any GL call. */
 public static void uploaded(VertexBufferObject vbo,Object vertices,int[] faces,Throwable failure){uploaded(vbo,vertices,faces,failure,false);}
 static void uploadedForTest(ModelMesh mesh,Object vertices,int[] faces,Throwable failure){uploaded(mesh.vb,vertices,faces,failure,true);}
 private static synchronized void uploaded(VertexBufferObject vbo,Object vertices,int[] faces,Throwable failure,boolean authored){if(vbo==null||(!authored&&!pinned.get(vbo.getClass())))return;for(var pair:new ArrayList<>(pending.entrySet())){var mesh=pair.getKey();var entry=pair.getValue();if(mesh==null||vertices!=entry.vertices||faces!=entry.faces)continue;try{
  if(failure!=null||!vbo.isStatic||mesh.modificationCount<entry.data.revision-1||mesh.modificationCount>entry.data.revision||!Arrays.equals(entry.data.vertices,positions(entry.vertices))||!Arrays.equals(entry.data.faces,entry.faces)){pending.remove(mesh);cache.remove(mesh);continue;}
  entry.vbo=vbo;entry.released();detail="Exact original phone FBX native VBO upload observed";
 }catch(RuntimeException|LinkageError unavailable){pending.remove(mesh);cache.remove(mesh);detail="Phone native upload changed";}}}
 public static synchronized Data get(ModelMesh mesh){var entry=cache.get(mesh);if(entry==null||entry.vbo==null||!mesh.isReady()||mesh.skinningData!=null||!mesh.hasVbo||mesh.vb==null||mesh.modificationCount!=entry.data.revision||!Objects.equals(entry.path,path(mesh))||!bounds(mesh,entry.bounds))return null;return entry.vbo==mesh.vb?entry.data:null;}
 public static String status(){return detail;}
 static synchronized void clearForTest(){cache.clear();pending.clear();}
 private NativeHeldFbxCpu(){}
}
